from (values
('127.568.d.1.A',3,'A guest sighs, checks a watch, and taps a foot while waiting in line. These are examples of what kind of communication?','["nonverbal", "formal", "electronic", "written"]'::jsonb,0,'Body language and sighs send messages without words, so they are nonverbal communication.','original'),
('127.568.d.1.A',4,'Speaking in a calm, friendly tone while keeping an open posture helps a host send a welcoming:','["invoice", "message", "recipe", "schedule"]'::jsonb,1,'Tone and posture are nonverbal cues that shape the message a guest receives.','original'),
('127.568.d.1.B',3,'A guest asks for extra pillows twice. The staff member should recognize the need and:','["ask the guest to wait a day", "charge extra fees", "bring them promptly", "ignore the request"]'::jsonb,2,'Repeated requests signal a real need, so respond quickly.','original'),
('127.568.d.1.B',4,'Asking, ''Is there anything else I can do for you?'' helps staff discover guest:','["debts", "nicknames", "hobbies", "needs"]'::jsonb,3,'Open offers of help uncover needs the guest has not yet mentioned.','original'),
('127.568.d.1.C',3,'Repeating a guest''s request back to confirm it is part of:','["active listening", "menu design", "fast typing", "cash handling"]'::jsonb,0,'Paraphrasing shows you heard correctly and lets the guest fix any mistake.','original'),
('127.568.d.1.C',4,'To accurately process a guest''s message, a listener should avoid:','["nodding", "interrupting", "taking notes", "making eye contact"]'::jsonb,1,'Interrupting causes missed details; nodding, notes, and eye contact help.','original'),
('127.568.d.1.D',3,'A hotel sharing positive news and community involvement to build a good image is practicing:','["inventory", "payroll", "public relations", "housekeeping"]'::jsonb,2,'Public relations builds goodwill between a business and the public.','original'),
('127.568.d.1.D',4,'A courteous reply to an online review, whether it is positive or negative, helps protect a business''s:','["insurance", "floor plan", "payroll", "reputation"]'::jsonb,3,'Professional replies show that the business cares, protecting its reputation.','original'),
('127.568.d.1.E',3,'A deaf guest may request a sign language:','["interpreter", "upgrade", "menu", "coupon"]'::jsonb,0,'An interpreter converts spoken words to signs and back.','original'),
('127.568.d.1.E',4,'Large-print menus and braille signs help serve guests with:','["pets", "visual impairments", "late arrivals", "large groups"]'::jsonb,1,'These services make information accessible to guests who have trouble seeing.','original'),
('127.568.d.2.A',3,'An effective job search plan starts with setting a goal and listing target:','["hobbies", "vacations", "employers", "holidays"]'::jsonb,2,'Knowing which employers to approach focuses the search.','original'),
('127.568.d.2.A',4,'A resume should list contact information, skills, education, and work:','["rumors", "complaints", "dreams", "experience"]'::jsonb,3,'Employers use a resume to see what you know and have done.','original'),
('127.568.d.2.B',3,'A server who learns the new ordering tablet quickly shows:','["flexibility", "avoidance", "stubbornness", "delay"]'::jsonb,0,'Adapting to new tools is flexibility.','original'),
('127.568.d.2.B',4,'Being open to training on new tasks helps employees keep up with industry:','["uniforms", "changes", "lunches", "rumors"]'::jsonb,1,'Hospitality tools and trends change often, so ongoing learning matters.','original'),
('127.568.d.2.C',3,'A worker who plans time for both shifts and family events is balancing work and:','["parking", "tax law", "personal life", "menu pricing"]'::jsonb,2,'Balancing job and home responsibilities prevents burnout.','original'),
('127.568.d.2.C',4,'Ranking tasks from most to least urgent is called:','["skipping", "procrastinating", "guessing", "prioritizing"]'::jsonb,3,'Prioritizing means doing the most important or urgent tasks first.','original'),
('127.568.d.2.D',3,'An electronic career portfolio is stored and shared in a:','["digital format", "paper folder", "glass jar", "phone book"]'::jsonb,0,'An electronic portfolio is kept on a computer or online so it can be shared easily.','original'),
('127.568.d.2.D',4,'Which item belongs in an electronic career portfolio?','["a game score", "a resume with certificates", "a vacation photo album", "a grocery list"]'::jsonb,1,'A portfolio highlights career documents such as a resume and certificates.','original'),
('127.568.d.2.E',3,'A person who is great with people but slow with math should identify these as strengths and:','["rewards", "salaries", "weaknesses", "vacations"]'::jsonb,2,'Honest self-assessment lists both strengths and weaknesses.','original'),
('127.568.d.2.E',4,'Knowing your own weaknesses helps you choose training that leads to:','["delay", "punishment", "boredom", "improvement"]'::jsonb,3,'Targeted training turns weaknesses into skills.','original'),
('127.568.d.2.F',3,'Earning extra certifications and taking on new duties can lead to a:','["promotion", "vacation", "suspension", "demotion"]'::jsonb,0,'Added skills and responsibility support advancement.','original'),
('127.568.d.2.F',4,'Employers often promote workers who show reliability, leadership, and strong:','["absences", "performance", "gossip", "complaints"]'::jsonb,1,'Consistent, high-quality work earns advancement.','original'),
('127.568.d.2.G',3,'A group that supports people in the same field with training and networking is a professional:','["rumor", "vacation", "organization", "penalty"]'::jsonb,2,'Professional organizations connect and train members of an industry.','original'),
('127.568.d.2.G',4,'Joining an industry association can give members access to job listings and:','["fines", "parking tickets", "rumors", "conferences"]'::jsonb,3,'Associations host conferences and events for learning and networking.','original'),
('127.568.d.2.H',3,'A document that proves you passed an industry exam is a:','["certification", "menu", "receipt", "brochure"]'::jsonb,0,'A certification shows you met an industry standard.','original'),
('127.568.d.2.H',4,'Before applying for a license, a candidate should research the steps, fees, and:','["rumors", "requirements", "holidays", "mascots"]'::jsonb,1,'Each license has specific requirements such as exams and training hours.','original'),
('127.568.d.2.I',3,'A report predicting how many hospitality jobs will open in ten years describes the job:','["uniform", "penalty", "outlook", "receipt"]'::jsonb,2,'Employment outlook estimates future job growth or decline.','original'),
('127.568.d.2.I',4,'Growth in tourism usually means more job openings, or higher:','["taxes", "fatigue", "debt", "demand"]'::jsonb,3,'More travelers create more demand for workers.','original'),
('127.568.d.2.J',3,'Shaking hands, saying ''please,'' and arriving on time are examples of business:','["etiquette", "debts", "penalties", "rumors"]'::jsonb,0,'Etiquette is the set of polite behaviors expected at work.','original'),
('127.568.d.2.J',4,'Silencing a phone during a meeting shows courtesy and good personal:','["weather", "manners", "debt", "luck"]'::jsonb,1,'Respecting others'' attention is part of personal etiquette.','original'),
('127.568.d.2.K',3,'A written rule about how to handle guest complaints is part of an organizational:','["costume", "rumor", "policy", "menu"]'::jsonb,2,'Policies put expectations in writing for everyone.','original'),
('127.568.d.2.K',4,'Written policies help every employee follow the same:','["desserts", "seasons", "rumors", "standards"]'::jsonb,3,'Shared written standards keep operations consistent.','original'),
('127.568.d.2.L',3,'A hotel manager''s job often requires leadership skills and a degree or years of:','["experience", "vacation", "sleep", "luck"]'::jsonb,0,'Managerial roles usually require education, experience, or both.','original'),
('127.568.d.2.L',4,'A manager''s major duties include scheduling staff, controlling costs, and handling guest:','["vacations", "complaints", "hobbies", "birthdays"]'::jsonb,1,'Managers solve problems and keep operations running smoothly.','original'),
('127.568.d.3.A',3,'A law that prevents employers from choosing workers based on race or gender is an anti-:','["taxation", "inflation", "discrimination", "recycling"]'::jsonb,2,'Anti-discrimination laws require fair hiring.','original'),
('127.568.d.3.A',4,'Unwelcome comments or behavior that make a workplace hostile are called:','["training", "teamwork", "promotion", "harassment"]'::jsonb,3,'Harassment is illegal and employers must prevent and address it.','original'),
('127.568.d.3.B',3,'A law is made by the government, while a policy is made by an:','["employer", "customer", "inspector", "guest"]'::jsonb,0,'Laws apply to everyone; policies are a company''s own rules.','original'),
('127.568.d.3.B',4,'A company''s dress code is an employer policy, but paying minimum wage is a legal:','["suggestion", "requirement", "option", "preference"]'::jsonb,1,'Employers must follow laws; policies are additional rules they choose.','original'),
('127.568.d.3.C',3,'A cashier finds extra money in the drawer and must choose whether to report it. This is an ethical:','["discount", "reward", "dilemma", "holiday"]'::jsonb,2,'An ethical dilemma is a choice between competing moral options.','original'),
('127.568.d.3.C',4,'To solve an ethical dilemma, a person should weigh honesty, fairness, and the effect on:','["weather", "menus", "prices", "others"]'::jsonb,3,'Ethical choices consider how people are affected.','original'),
('127.568.d.4.A',3,'A property management system helps a hotel track reservations and:','["room availability", "stock prices", "bus routes", "school grades"]'::jsonb,0,'The system shows which rooms are open, occupied, or being cleaned.','original'),
('127.568.d.4.A',4,'Restaurants use a reservation app to manage seating and reduce:','["tips", "wait times", "profits", "menus"]'::jsonb,1,'Reservation tools help seat guests efficiently.','original'),
('127.568.d.4.B',3,'To research a hotel''s services online, a student should visit the property''s official:','["brochure rack", "parking lot", "website", "receipt"]'::jsonb,2,'The official site gives accurate details about services.','original'),
('127.568.d.4.B',4,'A trustworthy hospitality website lists contact details and shows the date it was last:','["cooked", "painted", "rented", "updated"]'::jsonb,3,'A recent update date suggests the information is current.','original'),
('127.568.d.4.C',3,'Mobile check-in and keyless entry are examples of emerging:','["technologies", "holidays", "uniforms", "recipes"]'::jsonb,0,'Emerging technologies are new tools just entering the industry.','original'),
('127.568.d.4.C',4,'Before adopting new technology, a business should compare its cost and its:','["slogan", "benefits", "color", "nickname"]'::jsonb,1,'Weighing cost against benefits shows whether the tool is worth it.','original'),
('127.568.d.5.A',3,'Fair pay, recognition, and respect help a business keep employees, which is called:','["turnover", "forecasting", "retention", "inventory"]'::jsonb,2,'Employee retention means keeping workers; turnover is the opposite.','original'),
('127.568.d.5.A',4,'High employee turnover costs a business money because it must constantly:','["raise prices", "close early", "cut menus", "hire and train"]'::jsonb,3,'Replacing workers requires recruiting and training time.','original'),
('127.568.d.5.B',3,'A staff training plan should list skills to teach, who will teach them, and a:','["timeline", "slogan", "costume", "rumor"]'::jsonb,0,'A timeline shows when each training step happens.','original'),
('127.568.d.5.B',4,'Cross-training employees to do several jobs helps build an effective:','["menu", "team", "budget", "rumor"]'::jsonb,1,'Cross-trained staff can cover for each other.','original'),
('127.568.d.5.C',3,'Two coworkers disagree about a shift swap. A good first step is to listen to each side and stay:','["silent", "absent", "calm", "loud"]'::jsonb,2,'Staying calm keeps the discussion productive.','original'),
('127.568.d.5.C',4,'A solution in which both people give a little is called a:','["victory", "rumor", "penalty", "compromise"]'::jsonb,3,'A compromise meets both sides partway.','original'),
('127.568.d.5.D',3,'A guest finds the booked room is unavailable. The best response is to apologize and offer:','["an alternative", "a lecture", "an excuse", "silence"]'::jsonb,0,'Offering a solution keeps the guest''s trust.','original'),
('127.568.d.5.D',4,'When something unexpected happens, staff should stay calm and quickly:','["leave the area", "find a solution", "blame a coworker", "hide the problem"]'::jsonb,1,'Calm problem-solving turns surprises into good service.','original'),
('127.568.d.5.E',3,'Employees may have different holidays and customs because of their cultural:','["schedules", "paychecks", "backgrounds", "uniforms"]'::jsonb,2,'Culture shapes traditions and habits.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
