('127.568.d.6.B',4,'Promotional packages are designed to attract guests and increase:','["delays", "sales", "complaints", "costs"]'::jsonb,1,'Promotions aim to bring in more business.','original'),
('127.568.d.6.C',3,'Subtracting expenses from revenue leaves a business''s:','["tips", "debt", "profit", "payroll"]'::jsonb,2,'Profit is what remains after costs are paid.','original'),
