('127.569.d.2.C',4,'A server''s tip is 18% of a $50 bill. How much is the tip?','["$8.00", "$5.00", "$18.00", "$9.00"]'::jsonb,3,'0.18 x 50 = 9.','original'),
('127.569.d.2.D',3,'Bacteria multiply fastest between 41°F and 135°F, a range called the temperature danger:','["zone", "limit", "scale", "code"]'::jsonb,0,'Keep cold food cold and hot food hot to stay out of the danger zone.','original'),
('127.569.d.2.D',4,'Heating food to a safe internal temperature kills harmful:','["vitamins", "bacteria", "minerals", "flavors"]'::jsonb,1,'Cooking to the proper temperature destroys pathogens.','original'),
