('127.569.d.7.L',4,'Workers have a right to know about the chemicals they use, and employers must provide labels and:','["parking", "uniforms", "bonuses", "training"]'::jsonb,3,'Training teaches workers how to handle chemicals safely.','original'),
('127.569.d.7.M',3,'Employers must train workers on hazards before assigning them tasks that could cause:','["injury", "profit", "promotion", "praise"]'::jsonb,0,'Training is required to prevent harm.','original'),
