join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_77_v1'
from (values
('127.571.d.8.H',3,'Fuel for generators at an outdoor event should be stored in approved containers away from:','["picnic tables", "name tags", "open flames", "stage banners"]'::jsonb,2,'Fuel vapors can ignite near flames or sparks.','original'),
('127.571.d.8.H',4,'Before a crew uses a new cleaning chemical, they should read the product''s:','["advertisement", "price tag", "warranty", "safety data sheet"]'::jsonb,3,'The SDS explains hazards, handling, and first aid.','original'),
('127.571.d.8.I',3,'Event staff should know where first aid stations, exits, and fire extinguishers are located before guests:','["arrive", "eat", "dance", "leave"]'::jsonb,0,'Knowing resources in advance saves time in an emergency.','original'),
('127.571.d.8.I',4,'A site''s emergency plan should list contact numbers for police, fire, and medical:','["guests", "responders", "vendors", "speakers"]'::jsonb,1,'Quick contact with responders is vital in a crisis.','original'),
('127.571.d.8.J',3,'A safety and health program includes hazard prevention and control, training, and regular program:','["delay", "humor", "evaluation", "decoration"]'::jsonb,2,'Evaluation shows whether the program works.','original'),
('127.571.d.8.J',4,'Management shows commitment to safety by setting policies and providing the needed:','["holidays", "penalties", "rumors", "resources"]'::jsonb,3,'Leaders must supply time, money, and equipment for safety.','original'),
('127.571.d.8.K',3,'OSHA requires many employers to have written procedures for evacuating employees and for preventing:','["fires", "rumors", "parties", "sales"]'::jsonb,0,'Written plans guide evacuation and fire prevention.','original'),
('127.571.d.8.K',4,'An emergency action plan should name who is in charge, how to sound the alarm, and the routes for:','["promotion", "evacuation", "decoration", "registration"]'::jsonb,1,'Clear exit routes get everyone out safely.','original'),
('127.571.d.8.L',3,'Under hazard communication rules, employers must keep Safety Data Sheets easy for workers to:','["hide", "erase", "access", "sell"]'::jsonb,2,'Workers must be able to view SDS at any time.','original'),
('127.571.d.8.L',4,'Pictograms on chemical labels quickly show workers the type of:','["brand", "price", "flavor", "hazard"]'::jsonb,3,'Symbols communicate hazards such as flammable or corrosive.','original'),
('127.571.d.8.M',3,'OSHA requires safety training to be repeated when new hazards appear or when job tasks:','["change", "pay", "sell", "end"]'::jsonb,0,'Retraining is needed when risks or duties change.','original'),
('127.571.d.8.M',4,'Keeping records of who attended safety training provides proof of:','["profits", "compliance", "vacations", "promotions"]'::jsonb,1,'Training records show the employer met requirements.','original'),
('127.571.d.9.A',3,'A planner sending save-the-date emails and posting on social media to attract attendees is using event:','["insurance", "accounting", "marketing", "cleaning"]'::jsonb,2,'Marketing strategies promote an event to its audience.','original'),
('127.571.d.9.A',4,'Early-bird pricing encourages people to register sooner by offering a lower:','["tax", "fine", "wage", "price"]'::jsonb,3,'A discount rewards early registration.','original'),
('127.571.d.9.B',3,'A bundle that includes a meeting room, audiovisual equipment, and lunch for one price is called a promotional:','["package", "warning", "receipt", "permit"]'::jsonb,0,'Packages simplify buying and attract clients.','original'),
('127.571.d.9.B',4,'Offering a free night''s stay with a large group booking is a promotion that aims to win more:','["debt", "business", "fines", "rainfall"]'::jsonb,1,'Promotions are designed to bring in customers.','original'),
('127.571.d.9.C',3,'A menu for a conference should offer variety and consider guests'' dietary:','["mascots", "fonts", "restrictions", "slogans"]'::jsonb,2,'Menus should include options for allergies and special diets.','original'),
('127.571.d.9.C',4,'To keep catering costs within budget, a planner may choose seasonal ingredients and a limited number of:','["tablecloths", "speakers", "rooms", "entrees"]'::jsonb,3,'Fewer entree choices and seasonal foods lower costs.','original'),
('127.571.d.9.D',3,'When the economy is weak, companies often cut travel and meeting budgets, so planners may expect:','["fewer events", "more travel", "higher budgets", "larger crowds"]'::jsonb,0,'Economic downturns reduce meeting and travel spending.','original'),
('127.571.d.9.D',4,'A strong economy and low unemployment usually lead to more spending on conferences and:','["layoffs", "incentive trips", "closures", "pay cuts"]'::jsonb,1,'Healthy economies support more corporate meetings and rewards.','original'),
('127.571.d.9.E',3,'A business plan for an event company includes a description of services, market analysis, and financial:','["costumes", "fashions", "projections", "rumors"]'::jsonb,2,'Projections estimate future income and expenses.','original'),
('127.571.d.9.E',4,'A business plan for a new event company is often needed to secure a bank:','["vacation", "menu", "uniform", "loan"]'::jsonb,3,'Lenders review plans before providing funds.','original'),
('127.571.d.10.A',3,'A detailed customer service plan for an event starts by identifying what guests will expect and then assigning:','["responsibilities", "souvenirs", "penalties", "rumors"]'::jsonb,0,'Staff need clear roles to deliver great service.','original'),
('127.571.d.10.A',4,'Training greeters to welcome guests and answer questions is part of a plan to provide maximum customer:','["debt", "service", "delay", "rumor"]'::jsonb,1,'Prepared staff give guests a better experience.','original'),
('127.571.d.10.B',3,'A speaker cancels an hour before the keynote. A planner who calmly considers options and contacts a backup is using critical thinking and:','["delay", "blame", "interpersonal skills", "luck"]'::jsonb,2,'Good judgment and communication solve problems.','original'),
('127.571.d.10.B',4,'When a client is upset, a planner should first listen, then identify the problem, and then offer a:','["excuse", "rumor", "complaint", "solution"]'::jsonb,3,'Listening first leads to better solutions.','original'),
('127.571.d.10.C',3,'Post-event surveys give planners feedback they can use to find areas of:','["improvement", "punishment", "delay", "boredom"]'::jsonb,0,'Feedback shows what to improve next time.','original'),
('127.571.d.10.C',4,'If many survey responses say the room was too cold, the planner should note it and adjust the setup for the next:','["loan", "event", "holiday", "lawsuit"]'::jsonb,1,'Using feedback improves future services.','original'),
('127.571.d.11.A',3,'In a hotel, the department that handles group sales and event bookings is:','["housekeeping", "security", "sales and catering", "engineering"]'::jsonb,2,'This department sells meeting space and arranges food service.','original'),
('127.571.d.11.A',4,'The department that keeps equipment working and repairs rooms is:','["marketing", "accounting", "reservations", "engineering"]'::jsonb,3,'Engineering handles maintenance and repairs.','original'),
('127.571.d.11.B',3,'A corporate board meeting differs from a wedding reception because the client''s goals and the guest:','["expectations", "heights", "hair colors", "birthdays"]'::jsonb,0,'Each type of event serves a different purpose.','original'),
('127.571.d.11.B',4,'Planning a nonprofit fund-raising gala usually focuses on raising money, while a sales meeting focuses on teaching or motivating the:','["valets", "sales team", "donors", "caterers"]'::jsonb,1,'Event goals depend on the audience.','original'),
('127.571.d.11.C',3,'People or groups with an interest in an event''s success, such as sponsors, vendors, and attendees, are called:','["competitors", "trespassers", "stakeholders", "rivals"]'::jsonb,2,'Stakeholders are affected by or invested in the outcome.','original'),
('127.571.d.11.C',4,'The venue, caterer, and sponsors are all stakeholders in the success of the:','["weather", "menu", "lawsuit", "event"]'::jsonb,3,'Many groups depend on a successful event.','original'),
('127.571.d.12.A',3,'A person who plans the entire event from start to finish, working directly with the client, is the event:','["planner", "vendor", "sponsor", "guest"]'::jsonb,0,'The planner coordinates all aspects of an event.','original'),
('127.571.d.12.A',4,'Hotel staff who handle room setup, banquet service, and technical support for a group are the venue''s:','["guest list", "event services team", "speakers", "sponsors"]'::jsonb,1,'Venue staff carry out the planner''s requests on site.','original'),
('127.571.d.12.B',3,'An event manager is responsible for the budget, the schedule, and coordinating:','["tourists", "rivals", "vendors", "pets"]'::jsonb,2,'Managers work with suppliers such as caterers and decorators.','original'),
('127.571.d.12.B',4,'On the day of an event, the manager oversees setup, solves problems, and makes sure the program runs on:','["fire", "stage", "ice", "time"]'::jsonb,3,'Staying on schedule keeps guests satisfied.','original'),
('127.571.d.12.C',3,'Written checklists for room setup reduce errors and save time, which helps an event business control:','["costs", "guests", "traffic", "rainfall"]'::jsonb,0,'Efficiency lowers labor and rework costs.','original'),
('127.571.d.12.C',4,'Standard procedures for ordering, receiving, and inspecting supplies help prevent loss and:','["praise", "waste", "sales", "growth"]'::jsonb,1,'Good procedures reduce spoilage and theft.','original'),
('127.571.d.12.D',3,'Counting tables, chairs, and linens after each event so they are tracked and reordered is a type of:','["payroll", "menu design", "inventory control", "guest check-in"]'::jsonb,2,'Inventory control tracks equipment and supplies.','original'),
('127.571.d.12.D',4,'Using software to track rental items such as projectors and screens helps prevent loss and ensure each item is:','["promoted", "insured", "decorated", "available"]'::jsonb,3,'Tracking tells planners what is in stock.','original'),
('127.571.d.13.A',3,'A pre-event meeting with a potential client is held to learn their goals, budget, and:','["expectations", "birthdays", "hobbies", "pets"]'::jsonb,0,'Understanding expectations guides planning.','original'),
('127.571.d.13.A',4,'During a first meeting, a planner can show the venue and review sample menus to help the client decide whether to:','["quit", "book", "cancel", "retire"]'::jsonb,1,'Site visits and samples help clients decide.','original'),
('127.571.d.13.B',3,'A drawing of a venue showing room dimensions, exits, and fixed features is a:','["menu", "contract", "floor plan", "invoice"]'::jsonb,2,'Floor plans show the room''s layout.','original'),
('127.571.d.13.B',4,'A floorplan specification chart helps a planner decide how many tables and chairs will fit while keeping exits:','["locked", "hidden", "covered", "clear"]'::jsonb,3,'Exits must remain open for safety.','original'),
('127.571.d.13.C',3,'A setup with rows of chairs all facing the front, ideal for large lectures, is called:','["theater style", "U-shape", "classroom style", "banquet rounds"]'::jsonb,0,'Theater style packs in the most seats facing a stage.','original'),
('127.571.d.13.C',4,'Which setup places guests at round tables for dining and conversation?','["hollow square", "banquet style", "boardroom style", "theater style"]'::jsonb,1,'Banquet rounds suit meals and networking.','original'),
('127.571.d.13.D',3,'A narrow ballroom may not fit a horseshoe setup, so the planner may choose a different layout based on the room''s:','["color", "name", "shape", "age"]'::jsonb,2,'Room dimensions limit layout options.','original'),
('127.571.d.13.D',4,'Columns, low ceilings, and doorways can limit how a venue''s room can be:','["named", "priced", "painted", "arranged"]'::jsonb,3,'Physical features restrict setup choices.','original'),
('127.571.d.13.E',3,'A planner designing a workshop where attendees take notes at tables would most likely choose which setup?','["classroom style", "standing reception", "theater style", "cocktail rounds"]'::jsonb,0,'Classroom setup provides tables for writing.','original'),
('127.571.d.13.E',4,'A diagram of a planned room setup is shared with the venue so that staff set it up exactly as the planner:','["guessed", "intended", "hid", "forgot"]'::jsonb,1,'Clear diagrams prevent setup mistakes.','original'),
('127.571.d.13.F',3,'An event requires 10 square feet per guest for 150 guests. How many square feet are needed?','["150 sq ft", "15 sq ft", "1,500 sq ft", "15,000 sq ft"]'::jsonb,2,'10 x 150 = 1,500.','original'),
('127.571.d.13.F',4,'A room measures 40 feet by 30 feet. What is its area?','["70 sq ft", "140 sq ft", "12,000 sq ft", "1,200 sq ft"]'::jsonb,3,'Area = 40 x 30 = 1,200.','original'),
('127.571.d.13.G',3,'Placing the buffet so that guests can form two lines and not block the entrance is part of designing good traffic:','["flow", "fines", "tax", "jokes"]'::jsonb,0,'Good layout keeps people moving.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
